import java.io.*;
import java.util.*;

public class Main {
    static int[] dsuFa;  // 并查集
    static int[] left;   // 重构树左儿子
    static int[] right;  // 重构树右儿子
    static int[] val;    // 节点权值（合并时间）
    static int[] par;    // 重构树父节点
    static int[][] up;   // 倍增数组
    static int[] depth;
    static int[] rootId;
    static List<Integer>[] g;
    static int LOG = 20;

    static int dsuFind(int x) {
        if (dsuFa[x] != x) {
            dsuFa[x] = dsuFind(dsuFa[x]);
        }
        return dsuFa[x];
    }

    static void bfs(int root) {
        Queue<Integer> queue = new LinkedList<>();
        queue.offer(root);
        rootId[root] = root;
        depth[root] = 0;
        while (!queue.isEmpty()) {
            int u = queue.poll();
            up[0][u] = par[u];
            for (int i = 1; i < LOG; i++) {
                up[i][u] = up[i-1][up[i-1][u]];
            }
            for (int v : g[u]) {
                if (v != 0) {
                    depth[v] = depth[u] + 1;
                    rootId[v] = root;
                    queue.offer(v);
                }
            }
        }
    }

    static int lca(int u, int v) {
        if (rootId[u] != rootId[v]) return 0;
        if (depth[u] < depth[v]) {
            int tmp = u; u = v; v = tmp;
        }
        // 提升 u
        for (int i = LOG - 1; i >= 0; i--) {
            if (depth[u] - (1 << i) >= depth[v]) {
                u = up[i][u];
            }
        }
        if (u == v) return u;
        for (int i = LOG - 1; i >= 0; i--) {
            if (up[i][u] != up[i][v]) {
                u = up[i][u];
                v = up[i][v];
            }
        }
        return up[0][u];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int t = Integer.parseInt(st.nextToken());
        int q = Integer.parseInt(st.nextToken());

        int[] ops = new int[t];
        for (int i = 0; i < t; i++) {
            ops[i] = Integer.parseInt(br.readLine());
        }

        int maxN = n + t + 5;
        dsuFa = new int[maxN];
        left = new int[maxN];
        right = new int[maxN];
        val = new int[maxN];
        par = new int[maxN];

        for (int i = 0; i < maxN; i++) dsuFa[i] = i;

        int cur = n;
        for (int k = 1; k <= t; k++) {
            int x = ops[k-1];
            int fx = dsuFind(x);
            int fy = dsuFind(x + 1);
            if (fx != fy) {
                cur++;
                val[cur] = k;
                left[cur] = fx;
                right[cur] = fy;
                par[fx] = cur;
                par[fy] = cur;
                dsuFa[fx] = cur;
                dsuFa[fy] = cur;
            }
        }

        g = new ArrayList[cur + 1];
        for (int i = 0; i <= cur; i++) g[i] = new ArrayList<>();
        for (int i = n + 1; i <= cur; i++) {
            g[i].add(left[i]);
            g[i].add(right[i]);
        }

        up = new int[LOG][cur + 1];
        depth = new int[cur + 1];
        rootId = new int[cur + 1];

        // 找到所有根节点进行 BFS
        for (int i = 1; i <= cur; i++) {
            if (par[i] == 0) {
                bfs(i);
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            st = new StringTokenizer(br.readLine());
            int l = Integer.parseInt(st.nextToken());
            int r = Integer.parseInt(st.nextToken());
            if (l == r) {
                sb.append("0\n");
            } else {
                int ancestor = lca(l, r);
                if (ancestor == 0) sb.append("-1\n");
                else sb.append(val[ancestor]).append("\n");
            }
        }
        System.out.print(sb);
    }
}
