void bfs(int root) {
    queue<int> q;
    q.push(root);
    rootId[root] = root;
    depth[root] = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        up[0][u] = par[u];
        for (int i = 1; i < LOG; i++) {
