    left = [0] * size
    right = [0] * size
    val = [0] * size          # 合并时间
    par = [0] * size          # 重构树中的父节点

    def dsu_find(x):
        while dsu_fa[x] != x:
            dsu_fa[x] = dsu_fa[dsu_fa[x]]
            x = dsu_fa[x]
        return x

    cur = n  # 叶子节点占 1..n，新节点从 n+1 开始
    for k in range(1, t + 1):
        p = ops[k - 1]
        fp = dsu_find(p)
        fp1 = dsu_find(p + 1)
        if fp != fp1:
            cur += 1
            val[cur] = k          # 记录合并发生的实验编号
            left[cur] = fp
            right[cur] = fp1
            par[fp] = cur
            par[fp1] = cur
            # 合并连通块
            dsu_fa[fp] = cur
            dsu_fa[fp1] = cur

    # 构建树的有向图（父 -> 子）
    g = [[] for _ in range(cur + 1)]
    for i in range(n + 1, cur + 1):
        g[i].append(left[i])
        g[i].append(right[i])

    LOG = 20
    up = [[0] * (cur + 1) for _ in range(LOG)]
    depth = [0] * (cur + 1)
    root_id = [0] * (cur + 1)

    # 对所有重构树根节点进行 BFS
    for i in range(1, cur + 1):
        if par[i] == 0:   # 根节点
            root = i
            q_bfs = deque([root])
            root_id[root] = root
            while q_bfs:
                u = q_bfs.popleft()
                up[0][u] = par[u]
                for j in range(1, LOG):
                    up[j][u] = up[j - 1][up[j - 1][u]]
                for v in g[u]:
                    if v != 0:
                        depth[v] = depth[u] + 1
                        root_id[v] = root
                        q_bfs.append(v)

    def lca(u, v):
        if root_id[u] != root_id[v]:
            return 0
        if depth[u] < depth[v]:
            u, v = v, u
        for i in range(LOG - 1, -1, -1):
            if depth[u] - (1 << i) >= depth[v]:
                u = up[i][u]
        if u == v:
            return u
        for i in range(LOG - 1, -1, -1):
            if up[i][u] != up[i][v]:
                u = up[i][u]
                v = up[i][v]
        return up[0][u]

    out = []
    for _ in range(q):
        l, r = map(int, input().split())
        if l == r:
            out.append("0")
        else:
            anc = lca(l, r)
            if anc == 0:
                out.append("-1")
            else:
                out.append(str(val[anc]))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    main()
